bytes memory userData = "0x1";
tokens[0] = weth;
amounts[0] = loan_amount;
IBalancer(balancer).flashLoan(address(this), tokens, amounts, userData);
is_paused = false;
emit EFRestart(_amount, getVirtualPrice());
