uint256 len = block.number.safeSub(last_earn_block);
uint256 A = last_volume.safeMul(block_rate).safeMul(len).safeDiv(1e18);
uint256 B = getVolume().safeMul(block_rate).safeMul(len).safeDiv(1e18);

