function pause() public onlyOwner{
require(!is_paused, "paused");
_earnReward();
uint256 loan_amount = getDebt();

address[] memory tokens = new address[](1);
uint256[] memory amounts = new uint256[](1);
bytes memory userData = "0x2";
tokens[0] = weth;
amounts[0] = loan_amount;
